import request from '../utils/request';
export function getList(params) {
    return request({
        url: 'im/user/getList',
        params
    });
}
export function getDetail(params) {
    return request({
        url: 'im/user/getDetail',
        params
    });
}
export function register(data) {
    return request({
        url: 'im/user/add',
        method: 'post',
        data
    });
}
export function batchRegister(data) {
    return request({
        url: 'im/user/batchAdd',
        method: 'post',
        data
    });
}
export function edit(data) {
    return request({
        url: 'im/user/edit',
        method: 'post',
        data
    });
}
export function setUserId(userId) {
    return request({
        url: 'im/user/setUserId',
        method: 'post',
        data: {
            userId
        }
    });
}
